/**
 * Game audio on the scene PC (phones stay silent, SPEC section 9).
 *
 * Plain Web Audio, no Three.js: one AudioContext, a master bus with three groups (effects,
 * music, ambience), one-shot buffers and a few loops. Files live in public/assets/sounds/
 * (generated by scripts/generate-sounds.py; a recording can replace any file under the same name).
 *
 * Background song: if public/assets/music/background.mp3 exists it plays in every phase (full in
 * the lobby and results, ducked under the effects during a match); otherwise the generated
 * lobby-loop plays in the lobby and results only. The song file is git-ignored (the repo is public
 * and a song is usually somebody else's copyright): each scene PC drops its own file in.
 *
 * Driven by the renderer: `frame(state, events)` once per rendered frame. Browsers only start
 * audio after a user gesture, so `unlock()` runs on the host's first click or key press
 * (the scene often starts with Enter, not a click). M mutes and unmutes; the choice is remembered.
 */
import type { GameState, Phase, SimEvent } from '@shared/state.ts';

const BASE = '/assets/sounds/';
const FILES = [
  'cannon', 'explosion-water', 'splash-small', 'splash-big', 'water-cannon', 'torpedo-launch',
  'mortar-launch', 'firework-burst', 'shield-up', 'shield-hit', 'pickup', 'respawn', 'boost',
  'wood-bump', 'wood-scrape', 'horn', 'beep', 'water-lapping', 'seagulls', 'bells-distant',
  'lobby-loop', 'win-fanfare',
] as const;
export type SoundId = (typeof FILES)[number];

const MUSIC_URL = '/assets/music/background.mp3';
/** Background-song level per phase, relative to the music bus: ducked while the match runs. */
const SONG_LEVEL: Record<Phase, number> = { lobby: 1, results: 1, countdown: 0.7, battle: 0.5, suddendeath: 0.5 };

const MUTE_KEY = 'gr.muted';
/** Group levels: effects carry the game, music and ambience sit underneath. */
const LEVEL = { master: 0.9, sfx: 1.0, music: 0.32, ambience: 0.45 } as const;

interface PlayOptions {
  gain?: number;
  /** Playback rate; small random spread keeps repeats from sounding identical. */
  rate?: number;
  /** World x of the event: panned left/right across the map. */
  x?: number;
  /** Skip if the same key played less than this long ago (ms). */
  throttleMs?: number;
  key?: string;
  bus?: 'sfx' | 'music' | 'ambience';
}

interface Loop {
  src: AudioBufferSourceNode;
  gain: GainNode;
}

function readMuted(): boolean {
  try {
    return localStorage.getItem(MUTE_KEY) === '1';
  } catch {
    return false;
  }
}

export class GameAudio {
  private ctx: AudioContext | null = null;
  private master: GainNode | null = null;
  private buses: Record<'sfx' | 'music' | 'ambience', GainNode> | null = null;
  private readonly buffers = new Map<SoundId, AudioBuffer>();
  /** The optional background song (public/assets/music/background.mp3), or null. */
  private song: AudioBuffer | null = null;
  private readonly loops = new Map<string, Loop>();
  private readonly lastPlayed = new Map<string, number>();
  private phase: Phase | null = null;
  private muted = readMuted();
  private nextGullAt = 0;
  private nextBellAt = 0;
  private readonly onGesture = (): void => this.unlock();
  private readonly onKey = (e: KeyboardEvent): void => {
    if (e.code === 'KeyM' && !(e.target instanceof HTMLInputElement)) this.setMuted(!this.muted);
  };

  /** `halfWidth`: half the map width in metres, for left/right panning. */
  constructor(private readonly halfWidth: number) {
    window.addEventListener('pointerdown', this.onGesture);
    window.addEventListener('keydown', this.onGesture);
    window.addEventListener('keydown', this.onKey);
    // Dev console handle: grAudio.play('cannon'), grAudio.setMuted(true), grAudio.status().
    if (import.meta.env.DEV) Object.assign(window, { grAudio: this });
  }

  /** For the console and tests: what is loaded and playing. */
  status(): { state: string; loaded: number; of: number; song: boolean; loops: string[]; muted: boolean } {
    return { state: this.ctx?.state ?? 'locked', loaded: this.buffers.size, of: FILES.length, song: this.song !== null, loops: [...this.loops.keys()], muted: this.muted };
  }

  get isMuted(): boolean {
    return this.muted;
  }

  setMuted(on: boolean): void {
    this.muted = on;
    try {
      localStorage.setItem(MUTE_KEY, on ? '1' : '0');
    } catch {
      /* private mode: the choice just does not persist */
    }
    if (this.master && this.ctx) this.master.gain.setTargetAtTime(on ? 0 : LEVEL.master, this.ctx.currentTime, 0.05);
  }

  /** Create or resume the context. Must run inside a user gesture the first time. */
  unlock(): void {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') void this.ctx.resume();
      return;
    }
    const Ctor = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctor) return;
    const ctx = new Ctor();
    this.ctx = ctx;
    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : LEVEL.master;
    this.master.connect(ctx.destination);
    const bus = (level: number): GainNode => {
      const g = ctx.createGain();
      g.gain.value = level;
      g.connect(this.master as GainNode);
      return g;
    };
    this.buses = { sfx: bus(LEVEL.sfx), music: bus(LEVEL.music), ambience: bus(LEVEL.ambience) };
    window.removeEventListener('pointerdown', this.onGesture);
    window.removeEventListener('keydown', this.onGesture);
    void ctx.resume();
    void this.loadAll();
  }

  private async loadAll(): Promise<void> {
    const ctx = this.ctx;
    if (!ctx) return;
    await Promise.all([
      ...FILES.map(async (id) => {
        try {
          const res = await fetch(`${BASE}${id}.mp3`);
          if (!res.ok) return;
          this.buffers.set(id, await ctx.decodeAudioData(await res.arrayBuffer()));
        } catch {
          /* a missing or broken file only silences that one sound */
        }
      }),
      this.loadSong(ctx),
    ]);
    // Start what the current phase needs now that the files are here.
    const phase = this.phase;
    this.phase = null;
    if (phase) this.enterPhase(phase);
    this.loop('ambience', 'water-lapping', 0.8, 'ambience');
  }

  /** The song is optional: a missing file (the dev server answers with index.html) is not an error. */
  private async loadSong(ctx: AudioContext): Promise<void> {
    try {
      const res = await fetch(MUSIC_URL);
      if (!res.ok || !(res.headers.get('content-type') ?? '').startsWith('audio/')) return;
      this.song = await ctx.decodeAudioData(await res.arrayBuffer());
    } catch {
      this.song = null;
    }
  }

  /** Once per rendered frame. */
  frame(state: GameState, events: readonly SimEvent[]): void {
    if (state.phase !== this.phase) this.enterPhase(state.phase);
    if (!this.ctx || this.buffers.size === 0) return;
    for (const e of events) this.onEvent(e);
    this.updateStream(state);
    this.updateAmbience();
  }

  private enterPhase(phase: Phase): void {
    const previous = this.phase;
    this.phase = phase;
    if (!this.ctx || this.buffers.size === 0) return;
    if (this.song) this.loop('music', this.song, SONG_LEVEL[phase], 'music');
    else if (phase === 'lobby' || phase === 'results') this.loop('music', 'lobby-loop', 1, 'music');
    else this.stopLoop('music', 0.8);
    if (phase === 'battle' && previous === 'countdown') this.play('horn', { gain: 0.9 });
    if (phase === 'suddendeath') this.play('horn', { gain: 0.9, rate: 1.12 });
    if (phase !== 'battle' && phase !== 'suddendeath') this.stopLoop('stream', 0.1);
  }

  private onEvent(e: SimEvent): void {
    const jitter = (): number => 0.94 + Math.random() * 0.12;
    switch (e.kind) {
      case 'countdown':
        if (e.secondsLeft <= 3) this.play('beep', { gain: 0.7 });
        break;
      case 'fired':
        if (e.weapon === 'cannon') this.play('cannon', { x: e.x, rate: jitter(), gain: 1.0 });
        else if (e.weapon === 'torpedo') this.play('torpedo-launch', { x: e.x, rate: jitter() });
        else if (e.weapon === 'mortar') this.play('mortar-launch', { x: e.x, rate: jitter() });
        break; // the Water Cannon is a loop, see updateStream
      case 'hit':
        if (e.cause === 'watercannon') this.play('splash-small', { x: e.x, gain: 0.35, rate: 1.3 * jitter(), throttleMs: 140, key: `jet${e.victim}` });
        else this.play('explosion-water', { x: e.x, rate: jitter() });
        break;
      case 'sunk':
        this.play('splash-big', { x: e.x, gain: 0.9, rate: 0.9 });
        break;
      case 'shielded':
        this.play('shield-hit', { x: e.x });
        break;
      case 'respawn':
        this.play('respawn', { x: e.x, gain: 0.6 });
        break;
      case 'pickup':
        this.play('pickup', { x: e.x, gain: 0.7, rate: e.category === 'weapon' ? 1 : 1.12 });
        break;
      case 'power':
        if (e.power === 'shield') this.play('shield-up', { x: e.x });
        else if (e.power === 'boost') this.play('boost', { x: e.x });
        else if (e.power === 'mine') this.play('wood-bump', { x: e.x, gain: 0.6, rate: 0.7 });
        else if (e.power === 'wave') this.play('splash-big', { x: e.x, gain: 0.8 });
        else this.play('splash-small', { x: e.x, gain: 0.4, rate: 0.6 });
        break;
      case 'splash':
        if (e.size >= 5) {
          this.play('firework-burst', { x: e.x, gain: 0.8 });
          this.play('splash-big', { x: e.x, gain: 0.6 });
        } else this.play(e.size >= 2.5 ? 'splash-big' : 'splash-small', { x: e.x, gain: 0.6, rate: jitter(), throttleMs: 60, key: 'splash' });
        break;
      case 'wall': {
        const g = Math.min(1, e.speed / 8);
        if (g > 0.15) this.play('wood-bump', { x: e.x, gain: 0.25 + 0.6 * g, rate: jitter(), throttleMs: 250, key: `wall${e.team}` });
        if (e.speed > 3) this.play('wood-scrape', { x: e.x, gain: 0.25 * g, throttleMs: 600, key: `scrape${e.team}` });
        break;
      }
      case 'ram':
        this.play('wood-bump', { x: e.x, gain: 1, rate: 0.8 });
        if (e.lethal) this.play('explosion-water', { x: e.x, gain: 0.9 });
        break;
      case 'win':
        this.play('win-fanfare', { gain: 0.9 });
        break;
      default:
        break;
    }
  }

  /** Water Cannon: a loop whose level follows how many crews are spraying right now. */
  private updateStream(state: GameState): void {
    let spraying = 0;
    for (const b of state.boats) if (b.firing && b.weapon === 'watercannon' && b.status === 'alive') spraying++;
    if (spraying > 0 && (state.phase === 'battle' || state.phase === 'suddendeath')) {
      const loop = this.loop('stream', 'water-cannon', 0, 'sfx');
      if (loop && this.ctx) loop.gain.gain.setTargetAtTime(Math.min(0.9, 0.45 + 0.15 * spraying), this.ctx.currentTime, 0.04);
    } else {
      const loop = this.loops.get('stream');
      if (loop && this.ctx) loop.gain.gain.setTargetAtTime(0, this.ctx.currentTime, 0.08);
    }
  }

  /** Sparse gulls and distant bells over the water loop. */
  private updateAmbience(): void {
    const ctx = this.ctx;
    if (!ctx) return;
    const now = ctx.currentTime;
    if (this.nextGullAt === 0) {
      this.nextGullAt = now + 6 + Math.random() * 8;
      this.nextBellAt = now + 30 + Math.random() * 30;
    }
    if (now >= this.nextGullAt) {
      this.play('seagulls', { bus: 'ambience', gain: 0.55, x: (Math.random() * 2 - 1) * this.halfWidth, rate: 0.95 + Math.random() * 0.1 });
      this.nextGullAt = now + 14 + Math.random() * 16;
    }
    if (now >= this.nextBellAt) {
      this.play('bells-distant', { bus: 'ambience', gain: 0.5 });
      this.nextBellAt = now + 50 + Math.random() * 40;
    }
  }

  play(id: SoundId, opts: PlayOptions = {}): void {
    const ctx = this.ctx;
    const buffer = this.buffers.get(id);
    if (!ctx || !this.buses || !buffer) return;
    if (opts.throttleMs) {
      const key = opts.key ?? id;
      const last = this.lastPlayed.get(key) ?? -Infinity;
      const nowMs = ctx.currentTime * 1000;
      if (nowMs - last < opts.throttleMs) return;
      this.lastPlayed.set(key, nowMs);
    }
    const src = ctx.createBufferSource();
    src.buffer = buffer;
    src.playbackRate.value = opts.rate ?? 1;
    const gain = ctx.createGain();
    gain.gain.value = opts.gain ?? 1;
    let node: AudioNode = src.connect(gain);
    if (opts.x !== undefined && typeof ctx.createStereoPanner === 'function') {
      const pan = ctx.createStereoPanner();
      pan.pan.value = Math.max(-0.8, Math.min(0.8, (opts.x / this.halfWidth) * 0.8));
      node = node.connect(pan);
    }
    node.connect(this.buses[opts.bus ?? 'sfx']);
    src.start();
  }

  /** Start (or return) a named loop; `level` is the starting gain. */
  private loop(name: string, id: SoundId | AudioBuffer, level: number, bus: 'sfx' | 'music' | 'ambience'): Loop | null {
    const existing = this.loops.get(name);
    const ctx = this.ctx;
    if (existing) {
      if (ctx && level > 0) existing.gain.gain.setTargetAtTime(level, ctx.currentTime, 0.3);
      return existing;
    }
    const buffer = typeof id === 'string' ? this.buffers.get(id) : id;
    if (!ctx || !this.buses || !buffer) return null;
    const src = ctx.createBufferSource();
    src.buffer = buffer;
    src.loop = true;
    const gain = ctx.createGain();
    gain.gain.value = 0;
    gain.gain.setTargetAtTime(level, ctx.currentTime, 0.3);
    src.connect(gain).connect(this.buses[bus]);
    src.start();
    const l = { src, gain };
    this.loops.set(name, l);
    return l;
  }

  private stopLoop(name: string, fadeSec: number): void {
    const l = this.loops.get(name);
    const ctx = this.ctx;
    if (!l || !ctx) return;
    this.loops.delete(name);
    l.gain.gain.setTargetAtTime(0, ctx.currentTime, fadeSec / 3);
    l.src.stop(ctx.currentTime + fadeSec + 0.2);
  }

  dispose(): void {
    window.removeEventListener('pointerdown', this.onGesture);
    window.removeEventListener('keydown', this.onGesture);
    window.removeEventListener('keydown', this.onKey);
    void this.ctx?.close();
    this.ctx = null;
  }
}
